                # Mark user as offline and set return time
                online[user_id] = False
                return_time[user_id] = timestamp + 60

            elif event_type == 'MESSAGE':
                content = event[2]

                # Helper function to check if user is online at given timestamp
                def is_user_online(user_idx, ts):
                    if online[user_idx]:
                        return True
                    if return_time[user_idx] != -1 and return_time[user_idx] <= ts:
                        return True
                    return False

                if content == 'ALL':
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif content == 'HERE':
