class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # Compute d[i] = nums[i] - k
        d = [nums[i] - k for i in range(n)]
        total_zeros = sum(1 for x in d if x == 0)

        # If all elements are already k, we don't need to do any operation (effectively x=0).
        if total_zeros == n:
            return n

        # Determine the range of non-zero differences
        non_zero_vals = [x for x in d if x != 0]
        if not non_zero_vals:
            return n

        min_v = min(non_zero_vals)
        max_v = max(non_zero_vals)

        best = total_zeros  # Baseline: choose a subarray that doesn't help (or x=0 effectively)

        # Iterate over each possible target value v (the value of d[i] that we want to fix)
        for v in range(min_v, max_v + 1):
            # Build array b:
            #   b[i] = 1 if d[i] == v (this element will be fixed to k by adding x = -v)
            #   b[i] = -1 if d[i] == 0 (this element is originally k, but including it in the operation makes it k + x, which is not k unless x=0; we subtract 1 because we lose the chance to count it as k later)
            #   b[i] = 0 otherwise
            b = []
            for x in d:
                if x == v:
                    b.append(1)
                elif x == 0:
                    b.append(-1)
                else:
                    b.append(0)

            # Kadane's algorithm to find the maximum subarray sum of b
            current_sum = 0
            max_sub = float('-inf')
            for val in b:
                current_sum += val
                if current_sum > max_sub:
                    max_sub = current_sum
                if current_sum < 0:
                    current_sum = 0

            # If max_sub is still -inf, it means all subarrays are negative, but since we have at least one v, max_sub should be at least 1.
            if max_sub != float('-inf'):
                freq = max_sub + total_zeros
                if freq > best:
                    best = freq

        return best

class Solution:
    def maxDifference(self, s: str) -> int:
        from collections import Counter

        freq = Counter(s)

        # Find the maximum odd frequency and minimum even frequency
        max_odd = 0
        min_even = float('inf')

        for char, count in freq.items():
            if count % 2 == 1:
