    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Create a copy of the grid to avoid modifying the original
        result = [row[:] for row in grid]

        # Iterate through each diagonal identified by constant (i - j)
        # k ranges from -(n-1) to (n-1)
        for k in range(-(n-1), n):
            diag_vals = []
            # Collect elements in the current diagonal
            for i in range(n):
                j = i - k
                if 0 <= j < n:
                    diag_vals.append(result[i][j])

            # Sort based on the triangle type
            if k >= 0:
                # Bottom-left triangle (including middle diagonal) -> non-increasing
                diag_vals.sort(reverse=True)
            else:
                # Top-right triangle -> non-decreasing
                diag_vals.sort()

            # Place sorted values back into the grid
            idx = 0
            for i in range(n):
                j = i - k
                if 0 <= j < n:
                    result[i][j] = diag_vals[idx]
                    idx += 1

        return result

