class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]

        NEG_INF = -float('inf')
        # dp[p][i] = max sum of exactly p non-overlapping subarrays from nums[0:i]
        dp = [[NEG_INF] * (n + 1) for _ in range(k + 1)]

        # Base case: 0 subarrays have sum 0 for any prefix length
        for i in range(n + 1):
            dp[0][i] = 0

        # Fill DP table
        for p in range(1, k + 1):
            for i in range(1, n + 1):
                # Option 1: Skip the current element nums[i-1]
                skip_val = dp[p][i-1]

                # Option 2: Include nums[i-1] as the end of the p-th subarray
                take_val = NEG_INF
                # The p-th subarray is nums[j:i], length = i - j >= m => j <= i - m
                for j in range(i - m, i):
                    if dp[p-1][j] != NEG_INF:
                        current_sub_sum = prefix[i] - prefix[j]
                        total = dp[p-1][j] + current_sub_sum
                        if total > take_val:
                            take_val = total

                dp[p][i] = max(skip_val, take_val)

        return dp[k][n]

