    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        if n == 0:
            return 0

        # Create a list of baskets with their original indices
        basket_with_idx = []
        for i in range(n):
            basket_with_idx.append((baskets[i], i))

        # Sort baskets by capacity (primary) and original index (secondary)
        basket_with_idx.sort(key=lambda x: (x[0], x[1]))

        # Extract capacities for binary search
        caps = [b[0] for b in basket_with_idx]

        # Determine the size for the segment tree (next power of 2)
        m = 1
        while m < n:
            m *= 2

        # Initialize segment tree: tree[i] stores the leftmost free index in the range covered by node i
        tree = [-1] * (2 * m)

        # Set leaves: for each basket in the sorted list, the initial free index is its position
        for i in range(n):
            tree[m + i] = i

        # Build internal nodes: if left child has a free index, use it; otherwise, use right child
        for i in range(m - 1, 0, -1):
            left = 2 * i
            right = 2 * i + 1
            if tree[left] != -1:
                tree[i] = tree[left]
            else:
                tree[i] = tree[right]

        # Function to update the tree: mark a basket as used (set to -1)
        def update_tree(pos):
            idx = m + pos
            tree[idx] = -1
            while idx > 1:
                idx //= 2
                left = 2 * idx
                right = 2 * idx + 1
                if tree[left] != -1:
                    tree[idx] = tree[left]
                else:
                    tree[idx] = tree[right]

        # Function to find the first free index in [l, r]
        def find_first_free(l, r):
            if l > r:
                return -1
            l += m
            r += m
            while l <= r:
                if l % 2 == 1:
                    if tree[l] != -1:
                        return l - m
                    l += 1
                else:
                    l //= 2
                if r % 2 == 0:
                    if tree[r] != -1:
                        return r - m
                    r -= 1
                else:
                    r //= 2
            return -1

        unplaced_count = 0
        for f in fruits:
            # Find the first basket in the sorted list with capacity >= f
            p = bisect.bisect_left(caps, f)

            if p >= n:
                unplaced_count += 1
            else:
                # Find the first free basket in [p, n-1]
                idx = find_first_free(p, n - 1)
                if idx != -1:
                    update_tree(idx)
                else:
                    unplaced_count += 1

        return unplaced_count

