class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        ans = -1

        # For each index, find the minimum k such that nums[i] can be formed by a subset of val's 
        # from queries 0..k-1 that cover index i.
        for i in range(n):
            target = nums[i]
            if target == 0:
                # Already zero, no queries needed for this index
                continue

            # dp[s] = minimum query index (0-based) to achieve sum s
            # Initialize with sum 0 achieved before any query (index -1)
            dp = {0: -1}
            possible = False

            # Iterate through queries to build achievable sums
            for q_idx, (l, r, val) in enumerate(queries):
                # Check if this query covers index i
                if l <= i <= r:
                    new_dp = dp.copy()

                    # Try to extend existing sums
                    for s, last_q in dp.items():
                        new_s = s + val
                        if new_s == target:
                            possible = True
                            break
                        elif new_s <= target and (new_s not in new_dp or q_idx < new_dp[new_s]):
                            new_dp[new_s] = q_idx

                    if possible:
                        break

                    # Update dp for next iterations
                    dp = new_dp
                    # Note: If we break due to finding the target, we break the outer loop too.

            if not possible:
                return -1

            # The number of queries used is q_idx + 1 (since q_idx is 0-based)
            k_i = q_idx + 1
            ans = max(ans, k_i)

        return ans

