                set_i = set(properties[i])
                set_j = set(properties[j])
                if len(set_i & set_j) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                stack = [i]
                while stack:
                    node = stack.pop()
                    if not visited[node]:
                        visited[node] = True
                        for neighbor in adj[node]:
                            if not visited[neighbor]:
                                stack.append(neighbor)

        return components

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)
        ans = 0

        # Iterate over all possible substrings from s and t
        for i in range(n + 1):
            for j in range(i, n + 1):
                s_sub = s[i:j]
                for p in range(m + 1):
                    for q in range(p, m + 1):
                        t_sub = t[p:q]
                        cand = s_sub + t_sub
                        if cand == cand[::-1]:
                            ans = max(ans, len(cand))

        return ans

class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0

        # Check all adjacent pairs including the wrap-around pair (last and first)
        for i in range(n):
            # Compare current element with next element (handling circularity)
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff

        return max_diff

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count the frequency of each digit in the string
        from collections import Counter

        freq = Counter(s)

        # Iterate through adjacent pairs
        for i in range(len(s) - 1):
            first_digit = int(s[i])
            second_digit = int(s[i+1])

            # Check if digits are different
            if first_digit == second_digit:
                continue

            # Check if each digit appears exactly as many times as its numeric value
            if freq[first_digit] == first_digit and freq[second_digit] == second_digit:
                return s[i:i+2]

        return ""

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)

        for i in range(n):
            # Collect all valid neighbor indices (within [i-k, i+k] excluding i)
            neighbors = []
            start = max(0, i - k)
            end = min(n - 1, i + k)

            for j in range(start, end + 1):
                if j != i:
                    neighbors.append(nums[j])

            # If there are no neighbors (e.g., k=0 or out of bounds), then it's automatically good
            if not neighbors:
                total += nums[i]
            else:
                max_neighbor = max(neighbors)
                if nums[i] > max_neighbor:
                    total += nums[i]

        return total

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total_area = 0
        max_y = 0
        for x, y, l in squares:
            area = l * l
            total_area += area
            if y + l > max_y:
                max_y = y + l

        squares.sort(key=lambda sq: sq[1])

        low = 0.0
        high = float(max_y)

        for _ in range(60):
            mid = (low + high) / 2.0

            above_area = 0.0
            below_area = 0.0

            for x, y, l in squares:
                top = y + l
                if top <= mid:
                    below_area += l * l
                elif y >= mid:
                    above_area += l * l
                else:
                    h_below = min(mid - y, l)
                    h_above = l - h_below
                    below_area += h_below * l
                    above_area += h_above * l

            if above_area >= below_area:
                high = mid
            else:
                low = mid

        return low
